INSERT INTO public.listings (kind, title, description, property_type, transaction_type, governorate_id, district_id, price, budget_min, budget_max, area_sqm, bedrooms, bathrooms, posted_as, phone)
SELECT v.kind::public.listing_kind, v.title, v.descr, v.ptype::public.property_type, 'sale', g.id, d.id, v.price, v.bmin, v.bmax, v.area, v.beds, v.baths, v.posted::public.account_type, '+201001234567'
FROM (VALUES
 ('offer','شقة 3 غرف بالمهندسين','شقة مشطبة سوبر لوكس بموقع متميز','apartment','GIZ','المهندسين',4200000::numeric,NULL::numeric,NULL::numeric,120,3,2,'individual'),
 ('offer','فيلا مستقلة على البحر','فيلا بحديقة خاصة وإطلالة مباشرة','villa','ALX','سموحة',12500000,NULL,NULL,350,5,4,'agency'),
 ('offer','شقة تمليك بمدينة نصر','دور خامس بأسانسير، قريبة من الخدمات','apartment','CAI','مدينة ناصر',2650000,NULL,NULL,145,3,2,'individual'),
 ('request','مطلوب شقة بالمعادي','مطلوب شقة مفروشة لعائلة صغيرة','apartment','CAI','المعادى',NULL,800000,1500000,100,2,NULL,'individual'),
 ('request','مطلوب فيلا بالشيخ زايد','مطلوب فيلا بحديقة لا تقل عن 300 متر','villa','GIZ','الشيخ زايد',NULL,9000000,14000000,300,4,NULL,'agency'),
 ('request','مطلوب شقة بالمنصورة','مطلوب شقة قريبة من جامعة المنصورة','apartment','DK','المنصورة',NULL,700000,1200000,110,3,NULL,'individual')
) AS v(kind,title,descr,ptype,gov,dist,price,bmin,bmax,area,beds,baths,posted)
JOIN public.governorates g ON g.code = v.gov
JOIN public.districts d ON d.governorate_id = g.id AND d.name_ar = v.dist;

REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
REVOKE EXECUTE ON FUNCTION public.is_banned(uuid) FROM anon;
REVOKE EXECUTE ON FUNCTION public.has_listing_conversation(uuid, uuid, uuid) FROM anon;